parameters.jsCode:
// Build a shape compatible with the rest of the workflow (Build Email HTML, Build Custom Fields Update)
const distRes = $input.first().json;
const recipients = $('Documenso Create Recipients').first().json.recipients || [];
const docId = $('Documenso Build Recipients').first().json.documentId;
const envelopeId = $('Documenso Build Recipients').first().json.envelopeId;
const baseUrl = 'https://documenso-simarro.agentesialabs.com/sign';
// recipients order: c1 (signingOrder=1), maybe c2, vendedor (last)
const byOrder = [...recipients].sort((a,b) => (a.signingOrder||0) - (b.signingOrder||0));
const c1   = byOrder[0] || null;
const last = byOrder[byOrder.length - 1] || null;
const c2   = byOrder.length === 3 ? byOrder[1] : null;
function urlOf(r){ return r ? `${baseUrl}/${r.token}` : null; }
return [{ json: {
  submission_id: envelopeId,
  document_id: docId,
  lead_id:   $('Extract Drive FileId').first().json.lead_id,
  lead_name: $('Unpack Lead').first().json.name,
  submitters: {
    Vendedor:   { id: last && last.id, email: last && last.email, url: urlOf(last) },
    Comprador:  { id: c1 && c1.id,    email: c1 && c1.email,    url: urlOf(c1) },
    Comprador2: c2 ? { id: c2.id, email: c2.email, url: urlOf(c2) } : null,
  }
} }];

const leadId = $('Parse Kommo Payload').first().json.lead_id;
const ext = 'lead-' + leadId;
const resp = $input.first().json || {};
const docs = resp.documents || resp.data || (Array.isArray(resp) ? resp : []);
const ACTIVE = ['DRAFT', 'PENDING', 'COMPLETED'];
const existing = (docs || []).filter(d =>
  d && d.externalId === ext && ACTIVE.includes(String(d.status || '').toUpperCase())
);
const lead = $('Unpack Lead').first().json;
return [{ json: Object.assign({}, lead, { _doc_exists: existing.length > 0, _existing_doc_ids: existing.map(d => d.id) }) }];

const items = $input.all();
let pageCount = 2;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
  const txt = buf.toString('latin1');
  const m = txt.match(/\/Type\s*\/Page[^s]/g);
  if (m && m.length) pageCount = m.length;
} catch (e) {}
return [{ json: Object.assign({}, items[0].json, { pageCount }), binary: items[0].binary }];

// Reutilizar contacto existente si su PHONE coincide con el tel del vendedor (últimos 9 dígitos)
const phone = String($('Build Custom Fields Update').first().json.vendor.phone || '');
const want = phone.replace(/\D/g, '').slice(-9);
const res = $input.first().json || {};
const list = (res._embedded && res._embedded.contacts) || [];
let matched = null;
for (const c of list) {
  for (const cfv of (c.custom_fields_values || [])) {
    if (cfv.field_code !== 'PHONE') continue;
    for (const v of (cfv.values || [])) {
      const digits = String(v.value || '').replace(/\D/g, '').slice(-9);
      if (want && digits === want) { matched = c.id; break; }
    }
    if (matched) break;
  }
  if (matched) break;
}
return [{ json: { matched_contact_id: matched, candidates: list.length } }];

// Contacto vendedor: el reutilizado si hubo match, si no el recién creado (|| corto-circuita)
const matched = $('Resolve Vendor Match').first().json.matched_contact_id;
const vendor_contact_id = matched || $('Create Vendor Contact').first().json._embedded.contacts[0].id;
return [{ json: { vendor_contact_id, reused: Boolean(matched) } }];

const body = $input.first().json.body || $input.first().json;

let lead_id = null;
let status_id = null;

// Shape 1: manual curl { lead_id: 12345 }
if (body.lead_id) {
  lead_id = body.lead_id;
}

// Shape 2: Kommo form-encoded with literal bracket keys
// body['leads[status][0][id]'] = '12345'
if (!lead_id && body['leads[status][0][id]']) {
  lead_id = body['leads[status][0][id]'];
  status_id = Number(body['leads[status][0][status_id]']);
}

// Shape 3 (defensive): nested object if n8n ever parses it
if (!lead_id && body.leads && body.leads.status) {
  const change = Array.isArray(body.leads.status) ? body.leads.status[0] : body.leads.status['0'] || body.leads.status;
  if (change) {
    lead_id = change.id || change.lead_id;
    status_id = Number(change.status_id);
  }
}

if (!lead_id) {
  return [{ json: { skip: true, reason: 'no lead_id in payload' } }];
}

const EXPECTED_STATUS = 106758495;
if (status_id !== null && status_id !== EXPECTED_STATUS) {
  return [{ json: { skip: true, reason: 'status_id ' + status_id + ' != expected ' + EXPECTED_STATUS, lead_id } }];
}

return [{ json: { skip: false, lead_id: Number(lead_id), status_id } }];

const lead = $input.first().json;
const cfvMap = {};
for (const cfv of (lead.custom_fields_values || [])) {
  const v = cfv.values && cfv.values[0] && (cfv.values[0].value !== undefined ? cfv.values[0].value : cfv.values[0]);
  cfvMap[cfv.field_id] = v;
}

const submission_id = cfvMap[1375866];
const estado = cfvMap[1375868];

// Skip if the contract is already claimed/sent/signed. 'enviando' is the in-flight
// lock written BEFORE the Documenso side-effects, so retries that arrive after the
// claim are dropped even if the submission_id was not persisted yet.
if (estado === 'enviando' || estado === 'enviado_firma' || estado === 'firmado') {
  return [{ json: {
    already_sent: true,
    submission_id,
    estado,
    lead_id: lead.id,
    lead_name: lead.name,
    raw_lead: lead,
  } }];
}

return [{ json: { already_sent: false, raw_lead: lead } }];

const lead = $('Get Lead').first().json;
const cfv = lead.custom_fields_values || [];
const cfMap = {};
for (const c of cfv) { const v = c.values && c.values[0] && c.values[0].value; cfMap[c.field_id] = v; }
const nombreVendedor = cfMap[1375854] || 'Vendedor';
const tipoContrato = (cfMap[1375840] || 'promesa_compraventa').toLowerCase();
const TIPO_LABELS = { promesa_compraventa: 'Promesa de compraventa', promesa_supeditada: 'Promesa de compraventa supeditada', encargo_agente_unico: 'Encargo de venta en agente único', encargo_sin_exclusividad: 'Encargo de venta sin exclusividad', encargo_exclusividad: 'Encargo de venta en exclusividad', hoja_visita: 'Hoja de visita', arras: 'Arras', reserva: 'Reserva' };
const tipoLabel = TIPO_LABELS[tipoContrato] || 'Promesa de compraventa';
const url = $json.submitters.Vendedor.url;

const title_em = "completa";
const main_content = `<tr><td align="center" class="inner-pad" style="padding:18px 56px 0 56px;background-color:#ffffff;"><p style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#3F5651;margin:0;">Hola, <strong style="color:#0F1715;">${nombreVendedor}</strong>.</p></td></tr><tr><td align="center" class="inner-pad" style="padding:16px 56px 0 56px;background-color:#ffffff;"><p style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.7;color:#3F5651;margin:0;">Has recibido un contrato de <strong style="color:#0F1715;">${tipoLabel}</strong> de Simarro Properties para firmar como parte vendedora. Por favor, revisa el documento y firma cuando lo veas correcto.</p></td></tr><tr><td align="center" class="inner-pad" style="padding:32px 44px 0 44px;background-color:#ffffff;"><table border="0" cellpadding="0" cellspacing="0"><tr><td bgcolor="#0F4A38" style="background-color:#0F4A38;border-radius:4px;"><a class="cta-btn" href="${url}" target="_blank" style="display:inline-block;padding:16px 36px;font-family:Arial,Helvetica,sans-serif;font-size:15px;color:#FFFFFF;text-decoration:none;font-weight:bold;letter-spacing:2px;text-transform:uppercase;border-radius:4px;">Abrir y firmar el contrato</a></td></tr></table></td></tr><tr><td align="center" class="inner-pad" style="padding:12px 56px 0 56px;background-color:#ffffff;"><p style="font-family:Arial,Helvetica,sans-serif;font-size:12px;line-height:1.6;color:#7A8A85;margin:0;">O copia el enlace en tu navegador:<br/><a href="${url}" style="color:#0F4A38;word-break:break-all;">${url}</a></p></td></tr><tr><td align="center" class="inner-pad" style="padding:24px 56px 32px 56px;background-color:#ffffff;"><p style="font-family:Georgia,serif;font-size:14px;font-style:italic;color:#0F4A38;line-height:1.6;margin:0;">Si tienes alguna duda antes de firmar, responde a este correo o contacta con tu agente de Simarro Properties.</p></td></tr>`;
const html = `<!DOCTYPE html><html xmlns="http://www.w3.org/1999/xhtml"><head><meta http-equiv="Content-Type" content="text/html; charset=UTF-8" /><meta name="viewport" content="width=device-width, initial-scale=1.0" /><meta name="color-scheme" content="light only" /><title>Tu firma — Simarro Properties</title><style type="text/css">
    body { margin:0; padding:0; background-color:#0F1715; font-family:Arial,Helvetica,sans-serif; }
    table { border-collapse:collapse; mso-table-lspace:0pt; mso-table-rspace:0pt; }
    img { display:block; border:0; height:auto; outline:none; text-decoration:none; }
    @media only screen and (max-width:620px) {
      .outer { width:100% !important; }
      .inner-pad { padding:24px 20px !important; }
      .head-title { font-size:30px !important; }
      .hero-cell { height:200px !important; }
      .hero-logo { width:180px !important; }
      .data-body { padding:20px !important; }
      .footer-pad { padding:28px 20px !important; }
